api=async function(url,opt={}){let r=await fetch(url,{headers:{'Content-Type':'application/json'},...opt});if(r.status===401){showLogin();throw Error('Sessão expirada')}if(!r.ok){let x=await r.json().catch(()=>({}));throw Error(typeof x.detail==='string'?x.detail:JSON.stringify(x.detail||r.statusText))}return r.status===204?null:r.json()};
function showLogin(){document.getElementById('authOverlay').style.display='grid';document.getElementById('loginPassword').value='';document.getElementById('loginUser').focus()}
document.getElementById('loginForm').onsubmit=async e=>{e.preventDefault();let error=document.getElementById('loginError');error.textContent='Entrando…';let r=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:document.getElementById('loginUser').value,password:document.getElementById('loginPassword').value})});if(!r.ok){let x=await r.json().catch(()=>({}));error.textContent=x.detail||'Não foi possível entrar';return}location.reload()};
document.getElementById('logoutButton').onclick=async()=>{await fetch('/api/auth/logout',{method:'POST'});location.reload()};
function canOperate(){return netUser&&['superadmin','admin'].includes(netUser.role)}
function applyRole(){document.body.classList.add(`role-${netUser.role}`);document.getElementById('authOverlay').style.display='none';document.getElementById('account').textContent=`${netUser.display_name} · ${netUser.role}`;document.getElementById('logoutButton').style.display='inline-block';document.getElementById('issuesButton').style.display='inline-block';document.getElementById('continuousButton').style.display='inline-block';if(canOperate()){document.getElementById('manageMenu').style.display='inline-block';document.getElementById('settingsMenu').style.display='inline-block'}if(netUser.role!=='superadmin')for(let id of ['auditButton','usersButton','licenseButton'])document.getElementById(id)?.remove()}

const originalRefreshMarkers=refreshMarkers;
map.off('zoomend',originalRefreshMarkers);
refreshMarkers=function(){let z=map.getZoom(),popView=z<=15;for(let m of markers.values()){let hide=m.net.kind==='device'?popView:m.net.kind==='cto'?z<16:m.net.kind==='cloud'?z<14:false;if(hide){if(map.hasLayer(m))map.removeLayer(m)}else{m.setIcon(mkIcon(m.net));if(!map.hasLayer(m))m.addTo(map)}}siteMarkers.forEach(m=>{if(popView){if(!map.hasLayer(m))m.addTo(map)}else if(map.hasLayer(m))map.removeLayer(m)});refreshIssueVisibility()};
map.on('zoomend',refreshMarkers);
map.on('zoomend',renderOperatorCards);map.on('moveend',renderOperatorCards);

loadTopology=async function(){for(let[k,m]of markers)if(k.startsWith('device:')){map.removeLayer(m);markers.delete(k)}siteMarkers.splice(0).forEach(m=>map.removeLayer(m));let data=await api('/api/topology'),bounds=[],count=0;data.sites.forEach(s=>{bounds.push([s.latitude,s.longitude]);s.devices.forEach((d,i)=>{count++;d.kind='device';d.pop_id=s.id;d.pop_name=s.name;d.pop_latitude=s.latitude;d.pop_longitude=s.longitude;d.down=d.zabbix_hostid&&Number(d.availability)===2;d.planned=d.netbox_status==='planned';let atPop=d.latitude==null||d.longitude==null||(Math.abs(Number(d.latitude)-Number(s.latitude))<.000001&&Math.abs(Number(d.longitude)-Number(s.longitude))<.000001),p=atPop?offset(s.latitude,s.longitude,i,s.devices.length):[d.latitude,d.longitude];addMarker(d,p)});let label=s.name.replace(/^CENTRAL\s+/i,''),icon=L.divIcon({className:'',iconSize:[118,58],iconAnchor:[59,29],html:`<div class="pop-marker"><b>POP</b><span>${esc(label)}</span><small>${s.devices.length} host${s.devices.length===1?'':'s'}</small></div>`}),sm=L.marker([s.latitude,s.longitude],{icon,title:`POP ${label}`});sm.on('click',()=>map.setView([s.latitude,s.longitude],16));siteMarkers.push(sm)});if(bounds.length)map.fitBounds(bounds,{padding:[50,50]});document.getElementById('summary').textContent=`${data.sites.length} POPs · ${count} equipamentos`;await loadNodes();refreshMarkers()};

const originalStartMove=startMove,originalBeginLink=beginLink,originalChooseElementAt=chooseElementAt;
