function renderOntMapClients(){ontLayers.clearLayers();if(map.getZoom()<18)return;for(let client of ontData){let state=ontState(client.status),color=state==='online'?'#22c55e':state==='offline'?'#ef4444':'#94a3b8',line=L.polyline([[client.cto_latitude,client.cto_longitude],[client.latitude,client.longitude]],{color,weight:1.7,opacity:.9,interactive:false,className:'ont-map-line'}),icon=L.divIcon({className:'',iconSize:[25,25],iconAnchor:[12,12],html:`<div class="ont-house ${state}" title="${esc(client.ont_name||`ONT ${client.ont_number}`)}">⌂</div>`}),marker=L.marker([client.latitude,client.longitude],{icon,title:client.ont_name||`ONT ${client.ont_number}`,zIndexOffset:500});marker.on('click',()=>openOntPanel(client));line.addTo(ontLayers);marker.addTo(ontLayers)}}
