  section.querySelectorAll('.cto-output').forEach(card=>{let output=splitter.outputs.find(item=>item.output_number===Number(card.dataset.output)),edit=card.querySelector('.edit-cto-output'),customers=card.querySelector('.clients-cto-output'),link=card.querySelector('.link-cto-output');if(edit)edit.onclick=()=>editCtoOutput(m,output);if(customers)customers.onclick=()=>selectCtoClients(m,output);if(link)link.onclick=()=>beginCtoOutputLink(m,splitter,output)});section.querySelectorAll('.position-ont-map').forEach(button=>button.onclick=()=>{let client=splitter.outputs.flatMap(output=>output.clients).find(item=>Number(item.assignment_id)===Number(button.dataset.assignment));if(client)startOntPosition({...client,cto_name:m.net.name,output_name:splitter.outputs.find(output=>output.clients.includes(client))?.name,olt_id:splitter.olt_id,sfp:splitter.sfp})});section.querySelectorAll('.coordinates-ont').forEach(button=>button.onclick=()=>{let client=splitter.outputs.flatMap(output=>output.clients).find(item=>Number(item.assignment_id)===Number(button.dataset.assignment));if(client)setOntCoordinates(client)});let add=document.getElementById('addCtoClients'),config=document.getElementById('reconfigureCtoSplitter');if(add)add.onclick=()=>chooseCtoClientOutput(m,splitter);if(config)config.onclick=()=>configureCtoSplitter(m,splitter)
