async function appendOperatorToggle(m){let body=document.getElementById('panelBody'),group=operatorData.find(item=>Number(item.device_id)===Number(m.net.id));if(!body||!group?.interfaces?.length)return;let button=document.createElement('button');button.className='panel-action operator-host-toggle';function label(){button.textContent=operatorExpanded.has(Number(m.net.id))?'Fechar card de operadoras':'Mostrar operadoras no mapa'}label();button.onclick=()=>{let id=Number(m.net.id);if(operatorExpanded.has(id)){operatorExpanded.delete(id);operatorOpenZoom.delete(id)}else{operatorExpanded.add(id);operatorOpenZoom.set(id,map.getZoom())}label();renderOperatorCards();if(operatorExpanded.has(id))closePanel()};body.append(button)}
