async function saveOperatorCloud(provider,latlng){await api('/api/nodes',{method:'POST',body:JSON.stringify({name:provider.name,kind:'cloud',latitude:latlng.lat,longitude:latlng.lng})});pendingOperatorPosition=null;cancel();await loadNodes();refreshCloudProviders();map.setView(latlng,Math.max(map.getZoom(),15));flashHint(`${provider.name} adicionada ao mapa.`,5000)}
function operatorCoordinatesForm(provider){modal(`Adicionar ${provider.name}`,`<form id="operatorCoordinatesForm"><label>Latitude</label><input id="operatorLatitude" type="number" step="any" required><label>Longitude</label><input id="operatorLongitude" type="number" step="any" required><p id="operatorCoordinatesError" class="form-error"></p><button class="primary">Adicionar nuvem</button></form>`);document.getElementById('operatorCoordinatesForm').onsubmit=async event=>{event.preventDefault();try{await saveOperatorCloud(provider,L.latLng(Number(document.getElementById('operatorLatitude').value),Number(document.getElementById('operatorLongitude').value)))}catch(error){document.getElementById('operatorCoordinatesError').textContent=error.message}}}
function addOperatorToMap(){let providers=providerCatalog(),placed=new Set([...markers.values()].filter(marker=>marker.net.kind==='cloud').map(marker=>marker.net.name.toLocaleLowerCase('pt-BR'))),available=providers.filter(provider=>!placed.has(provider.name.toLocaleLowerCase('pt-BR')));modal('Adicionar operadora ao mapa',available.length?`<p>Escolha uma operadora já cadastrada nas interfaces.</p>${available.map((provider,index)=>`<button class="iface choose-map-operator" data-index="${index}"><b>${esc(provider.name)}</b><br><small>${provider.interfaces.length} interface${provider.interfaces.length===1?'':'s'} cadastrada${provider.interfaces.length===1?'':'s'}</small></button>`).join('')}`:'<p class="muted">Todas as operadoras cadastradas já estão no mapa, ou ainda não há operadoras vinculadas às interfaces.</p>');document.querySelectorAll('.choose-map-operator').forEach(button=>button.onclick=()=>{let provider=available[Number(button.dataset.index)];modal(`Posicionar ${provider.name}`,`<button id="operatorPlaceMap" class="iface"><b>Posicionar no mapa</b><br><small>Clique no ponto onde a nuvem deve aparecer.</small></button><button id="operatorPlaceCoordinates" class="iface"><b>Informar coordenadas</b></button>`);document.getElementById('operatorPlaceMap').onclick=()=>{closeModal();pendingOperatorPosition=provider;mode='operator-position';document.getElementById('cancel').style.display='inline-block';hint(`Clique no mapa para posicionar a operadora ${provider.name}.`)};document.getElementById('operatorPlaceCoordinates').onclick=()=>operatorCoordinatesForm(provider)})}
