function openOperatorCloud(m){let provider=m.net.provider||providerCatalog().find(item=>item.name.toLocaleLowerCase('pt-BR')===m.net.name.toLocaleLowerCase('pt-BR'));if(!provider){showPanel(`<h2>${esc(m.net.name)}</h2><p class="muted">Operadora ainda sem interfaces vinculadas.</p>`);return}showPanel(`<h2>${esc(provider.name)}</h2><div class="panel-meta">Operadora · ${provider.interfaces.length} interface${provider.interfaces.length===1?'':'s'}</div><div class="operator-cloud-info">${provider.interfaces.map(item=>{let metrics=item.metrics||{},state=metrics.status||'unknown';return`<article class="operator-cloud-provider"><h3>${esc(item.subtitle||item.interface_name)}</h3><small>${esc(item.interface_name)} · ${esc(item.address_family==='dual'?'IPv4 e IPv6':item.address_family.toUpperCase())}</small><b class="${state==='up'?'updot':state==='down'?'downdot':'unkdot'}">● ${esc(statusText(state))}</b><small>Download ${esc(formatRate(metrics.download))} · Upload ${esc(formatRate(metrics.upload))}</small></article>`}).join('')}</div>${canOperate()?`<label class="operator-upload">${provider.image_url?'Substituir':'Adicionar'} logo da operadora<input id="operatorCloudLogo" type="file" accept="image/png,image/jpeg,image/webp,image/gif"></label><button id="operatorCloudLink" class="panel-action">Criar enlace para esta operadora</button><button id="moveOperatorCloud" class="panel-action">Mover no mapa</button>`:''}`);let upload=document.getElementById('operatorCloudLogo');if(upload)upload.onchange=async event=>{let file=event.target.files[0];if(!file)return;if(file.size>2*1024*1024){flashHint('A imagem deve possuir no máximo 2 MB.',5000);return}try{await api(`/api/operator-interfaces/${provider.interfaces[0].id}/image`,{method:'PUT',headers:{'Content-Type':file.type},body:file});await loadOperatorCards();openOperatorCloud(m);flashHint('Logo da operadora atualizada.',5000)}catch(error){flashHint(error.message,6000)}};let link=document.getElementById('operatorCloudLink');if(link)link.onclick=()=>beginLink(m,null);let move=document.getElementById('moveOperatorCloud');if(move)move.onclick=()=>startMove(m)}

function continuousAlertStops(){let stops=[],seen=new Set();for(let issue of currentIssues.filter(item=>item.status!=='resolved')){let point=null,bounds=null;if(issue.target_kind==='link'){let link=links.find(item=>Number(item.id)===Number(issue.target_id));if(link){seen.add(`link:${link.id}`);if(issue.latitude!=null&&issue.longitude!=null)point=L.latLng(Number(issue.latitude),Number(issue.longitude));else{bounds=L.latLngBounds((link.display_coordinates||link.geometry.coordinates).map(item=>[item[1],item[0]]));point=linkMidpoint(link.display_coordinates||link.geometry.coordinates)}}}else{let marker=markers.get(`${issue.target_kind==='device'?'device':'cto'}:${issue.target_id}`)||markers.get(`host:${issue.target_id}`);if(marker)point=marker.getLatLng()}if(point)stops.push({type:'alert',name:`${issueLabel(issue.severity)} · ${issue.target_name}`,detail:issue.description,point,bounds})}for(let link of links.filter(item=>item.status==='down')){let key=`link:${link.id}`;if(seen.has(key))continue;let coordinates=link.display_coordinates||link.geometry.coordinates;stops.push({type:'alert',name:`Enlace DOWN · ${link.name}`,detail:`${link.source_name} → ${link.target_name}`,point:linkMidpoint(coordinates),bounds:L.latLngBounds(coordinates.map(item=>[item[1],item[0]]))})}return stops}
function continuousStops(){let pops=siteMarkers.map(marker=>({name:marker.options.title||'POP',point:marker.getLatLng(),type:'pop'})),alerts=continuousAlertStops(),stops=[];pops.forEach((pop,index)=>{stops.push(pop);alerts.filter((_,alertIndex)=>alertIndex%Math.max(1,pops.length)===index).forEach(alert=>stops.push(alert))});if(pops.length){let bounds=L.latLngBounds(pops.map(item=>item.point));stops.push({name:'Rede inteira',bounds,type:'network'})}return stops}
function stopContinuousView(){continuousActive=false;clearTimeout(continuousTimer);continuousTimer=null;document.body.classList.remove('continuous-mode');document.getElementById('continuousExit')?.remove();document.getElementById('continuousCard')?.remove();map.invalidateSize()}
function runContinuousStop(advance=false){if(!continuousActive)return;let stops=continuousStops();if(!stops.length){stopContinuousView();flashHint('Cadastre pelo menos um POP para usar a visualização contínua.',5000);return}if(advance)continuousIndex=(continuousIndex+1)%stops.length;let selectedIndex=continuousIndex%stops.length,current=stops[selectedIndex],next=stops[(selectedIndex+1)%stops.length],card=document.getElementById('continuousCard');card.classList.toggle('alert-stop',current.type==='alert');card.innerHTML=`<b>${esc(current.type==='alert'?'⚠ '+current.name:current.name)}</b>${current.detail?`<small>${esc(current.detail)}</small>`:''}<small>Próxima: ${esc(next.name)} · clique para avançar</small>`;clearTimeout(continuousTimer);if(current.type==='network'){map.flyToBounds(current.bounds,{padding:[55,55],duration:2.8});continuousTimer=setTimeout(()=>runContinuousStop(true),60000);return}if(current.type==='alert'){if(current.bounds&&current.bounds.isValid()&&current.bounds.getNorthEast().distanceTo(current.bounds.getSouthWest())>15)map.flyToBounds(current.bounds,{padding:[150,150],maxZoom:20,duration:2.8});else map.flyTo(current.point,20,{animate:true,duration:2.8});continuousTimer=setTimeout(()=>runContinuousStop(true),10000);return}map.flyTo(current.point,20,{animate:true,duration:2.8});continuousTimer=setTimeout(()=>{if(!continuousActive||continuousIndex%stops.length!==selectedIndex)return;card.innerHTML=`<b>${esc(current.name)} · visão ampliada</b><small>Próxima: ${esc(next.name)} · clique para avançar</small>`;map.flyTo(current.point,17,{animate:true,duration:2});continuousTimer=setTimeout(()=>runContinuousStop(true),5000)},10000)}
function startContinuousView(){if(continuousActive)return;closePanel();closeModal();continuousActive=true;continuousIndex=0;document.body.classList.add('continuous-mode');document.body.insertAdjacentHTML('beforeend','<button id="continuousExit" class="continuous-exit">Sair da visualização</button><div id="continuousCard" class="continuous-card"></div>');document.getElementById('continuousExit').onclick=stopContinuousView;document.getElementById('continuousCard').onclick=()=>runContinuousStop(true);map.invalidateSize();runContinuousStop()}
document.getElementById('continuousButton').onclick=startContinuousView;

function activeNetworkAlerts(){let alerts=currentIssues.filter(issue=>issue.status!=='resolved').map(issue=>({key:`issue:${issue.id}`,title:`${issueLabel(issue.severity)} · ${issue.target_name}`,detail:issue.description}));for(let link of links.filter(item=>item.status==='down'))alerts.push({key:`link:${link.id}:down`,title:`Enlace offline · ${link.name}`,detail:`${link.source_name} → ${link.target_name}`});return alerts}
async function updateCriticalAlerts(){if(!netUser||alertUpdateRunning)return;alertUpdateRunning=true;try{let alerts=activeNetworkAlerts(),keys=alerts.map(alert=>alert.key),response=await api('/api/alert-acknowledgements/sync',{method:'POST',body:JSON.stringify({active_keys:keys})}),acked=new Set(response.acknowledged||[]),pending=alerts.filter(alert=>!acked.has(alert.key)),recognized=alerts.length-pending.length;document.getElementById('criticalAlert')?.remove();document.getElementById('ackAlertBar')?.remove();if(pending.length){let alert=pending[0];document.body.insertAdjacentHTML('beforeend',`<div id="criticalAlert" class="critical-alert"><b>${esc(alert.title)}</b><small>${esc(alert.detail||'Atenção necessária na rede.')}${pending.length>1?` · mais ${pending.length-1} alerta${pending.length===2?'':'s'}`:''}</small><div class="critical-alert-actions"><button id="ackCriticalAlert">Reconhecer alerta</button><span>O alerta continuará disponível na barra.</span></div></div>`);document.getElementById('ackCriticalAlert').onclick=async()=>{await api('/api/alert-acknowledgements',{method:'POST',body:JSON.stringify({alert_key:alert.key})});updateCriticalAlerts()}}if(recognized)document.body.insertAdjacentHTML('beforeend',`<div id="ackAlertBar" class="ack-alert-bar">${recognized} alerta${recognized===1?'':'s'} reconhecido${recognized===1?'':'s'}</div>`)}finally{alertUpdateRunning=false}}
async function openCtoDialog(m){closePanel();showLinkDialog(`<div id="ctoDialogBody" class="cto-dialog-body"><div class="cto-dialog-hero"><span class="cto-dialog-icon">◇</span><div><h2>${esc(m.net.name)}</h2><small>CTO · distribuição óptica, portas do splitter e clientes</small></div></div><div class="panel-meta">Carregando estrutura da CTO…</div></div>`);await appendCtoDistribution(m);let body=document.getElementById('ctoDialogBody'),actions=document.createElement('div');actions.className='cto-dialog-actions';if(canOperate()){let remove=document.createElement('button');remove.className='panel-action danger';remove.textContent='Excluir CTO';remove.onclick=()=>deleteCtoConfirmed(m);actions.append(remove)}let report=document.createElement('button');report.className='panel-action';report.textContent='Reportar erro';report.onclick=()=>openIssueForm({kind:'node',id:m.net.id,name:m.net.name});actions.append(report);body.append(actions);activeMetricsPanel=null}
openHostPanel=async function(m){if(m.net.kind==='cto'){await openCtoDialog(m);return}if(m.net.kind==='cloud'){openOperatorCloud(m);return}await originalOpenHostPanel(m);if((m.net.kind==='device'||m.net.kind==='host')&&canOperate()&&!document.getElementById('provisionalHostLink')){let provisional=document.createElement('button');provisional.id='provisionalHostLink';provisional.className='panel-action';provisional.textContent='Criar enlace provisório';provisional.onclick=()=>beginLink(m,null);document.getElementById('panelBody').append(provisional)}if(m.net.kind==='device'){await appendBgpPanel(m);await appendOperatorToggle(m)}if(m.net.kind==='host'&&canOperate()){let b=document.createElement('button');b.id='validateProvisionalHost';b.className='panel-action';b.textContent='Validar com host do Zabbix';b.onclick=()=>validateProvisionalHost(m);document.getElementById('panelBody').append(b)}if(m.net.kind==='device'&&canOperate()){let b=document.createElement('button');b.id='deleteHost';b.className='panel-action danger';b.textContent='Excluir Host';b.onclick=()=>deleteHostConfirmed(m);document.getElementById('panelBody').append(b)}reportButton({kind:m.net.kind==='device'?'device':'node',id:m.net.id,name:m.net.name});activeMetricsPanel=m.net.kind==='device'?{kind:'host',markerKey:`device:${m.net.id}`} :null};
const originalOpenLinkPanel=openLinkPanel;
openLinkPanel=async function(l,layer,clickedLatLng=null){let issuePoint=clickedLatLng||l._clickedLatLng||activeMetricsPanel?.clickedLatLng;await originalOpenLinkPanel(l,layer,issuePoint);if(netUser.role!=='superadmin'){let del=document.getElementById('deleteLink');if(del)del.remove()}if(!canOperate()){for(let id of ['editLink','renameLink','replaceSourceInterface','replaceTargetInterface','insertCtoInLink']){let button=document.getElementById(id);if(button)button.remove()}}reportButton({kind:'link',id:l.id,name:l.name,latitude:issuePoint?.lat,longitude:issuePoint?.lng});activeMetricsPanel={kind:'link',id:Number(l.id),clickedLatLng:issuePoint}};
const originalClosePanel=closePanel;
closePanel=function(){activeMetricsPanel=null;originalClosePanel()};

function roadPointKey(p){return`${Number(p[0]).toFixed(5)},${Number(p[1]).toFixed(5)}`}
function roadSegmentKey(a,b){let x=roadPointKey(a),y=roadPointKey(b);return x<y?`${x}|${y}`:`${y}|${x}`}
function laneNumber(index,count){return index-(count-1)/2}
function linkWeight(){let z=map.getZoom();return z<=11?1.5:z===12?2:z===13?3:z===14?4:5}
function ponInterface(name){return/(?:^|\s)(?:XGS?-?PON|GPON|PON)\s*[-:]?\s*\d+\/\d+\/\d+/i.test(name||'')}
function ponFlowCoordinates(link,coordinates){let sourcePon=ponInterface(link.source_interface_name),targetPon=ponInterface(link.target_interface_name);if(!sourcePon&&!targetPon)return null;return targetPon&&!sourcePon?[...coordinates].reverse():coordinates}
function separatedCoordinates(link,segments){let cs=link.geometry.coordinates.map(p=>[Number(p[0]),Number(p[1])]);if(cs.length<2)return cs;let offsets=cs.map(()=>({x:0,y:0,n:0})),spacing=linkWeight()+2;for(let i=0;i<cs.length-1;i++){let group=segments.get(roadSegmentKey(cs[i],cs[i+1]))||[link],ordered=[...group].sort((a,b)=>Number(a.id)-Number(b.id)),lane=laneNumber(ordered.findIndex(x=>Number(x.id)===Number(link.id)),ordered.length);if(!lane)continue;let a=map.latLngToLayerPoint([cs[i][1],cs[i][0]]),b=map.latLngToLayerPoint([cs[i+1][1],cs[i+1][0]]),dx=b.x-a.x,dy=b.y-a.y,n=Math.hypot(dx,dy);if(!n)continue;let ox=-dy/n*lane*spacing,oy=dx/n*lane*spacing;for(let j of [i,i+1]){offsets[j].x+=ox;offsets[j].y+=oy;offsets[j].n++}}return cs.map((p,i)=>{let o=offsets[i];if(!o.n)return p;let base=map.latLngToLayerPoint([p[1],p[0]]),ll=map.layerPointToLatLng([base.x+o.x/o.n,base.y+o.y/o.n]);return[ll.lng,ll.lat]})}
function pointSegmentDistance(p,a,b){let dx=b.x-a.x,dy=b.y-a.y;if(!dx&&!dy)return p.distanceTo(a);let t=Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy))),x=a.x+t*dx,y=a.y+t*dy;return Math.hypot(p.x-x,p.y-y)}
function linksNear(latlng){let p=map.latLngToLayerPoint(latlng);return links.filter(l=>!(l.trunk_group&&!l.is_trunk)).filter(l=>{let cs=l.display_coordinates||l.geometry.coordinates;for(let i=1;i<cs.length;i++){let a=map.latLngToLayerPoint([cs[i-1][1],cs[i-1][0]]),b=map.latLngToLayerPoint([cs[i][1],cs[i][0]]);if(pointSegmentDistance(p,a,b)<=11)return true}return false}).sort((a,b)=>Number(a.id)-Number(b.id))}
function chooseLinkAt(latlng,fallback){let p=map.latLngToLayerPoint(latlng),display=fallback.display_coordinates||fallback.geometry.coordinates,best={distance:Infinity,index:1};for(let i=1;i<display.length;i++){let a=map.latLngToLayerPoint([display[i-1][1],display[i-1][0]]),b=map.latLngToLayerPoint([display[i][1],display[i][0]]),distance=pointSegmentDistance(p,a,b);if(distance<best.distance)best={distance,index:i}}let original=fallback.geometry.coordinates,key=roadSegmentKey(original[best.index-1],original[best.index]),nearby=links.filter(l=>!(l.trunk_group&&!l.is_trunk)).filter(l=>{let cs=l.geometry.coordinates;for(let i=1;i<cs.length;i++)if(roadSegmentKey(cs[i-1],cs[i])===key)return true;return false}).sort((a,b)=>Number(a.id)-Number(b.id));if(nearby.length<2){let layer=linkLayers.get(Number(fallback.id));if(layer)openLinkPanel(fallback,layer,latlng);return}let popup=L.popup({maxWidth:360}).setLatLng(latlng).setContent(`<div class="link-menu"><b>${nearby.length} enlaces neste trecho</b>${nearby.map(l=>`<button class="choose-overlap-link" data-id="${l.id}"><span class="${l.status==='up'?'updot':l.status==='down'?'downdot':'unkdot'}">●</span> ${esc(l.name)}${l.is_trunk?'<br><small>Eth-Trunk</small>':l.route_mode==='suggested'?'<br><small>Trajeto sugerido</small>':''}</button>`).join('')}</div>`).openOn(map);setTimeout(()=>document.querySelectorAll('.choose-overlap-link').forEach(b=>b.onclick=()=>{let l=links.find(x=>Number(x.id)===Number(b.dataset.id)),layer=linkLayers.get(Number(b.dataset.id));map.closePopup(popup);if(l&&layer)openLinkPanel(l,layer,latlng)}),0)}
function renderLinks(){
 editable.clearLayers();suggestedBorders.clearLayers();ponFlowLayers.clearLayers();linkLayers.clear();
 let visibleLinks=links.filter(l=>!(l.trunk_group&&!l.is_trunk)),segments=new Map(),weight=linkWeight();
 visibleLinks.forEach(l=>{let cs=l.geometry.coordinates;for(let i=1;i<cs.length;i++){let key=roadSegmentKey(cs[i-1],cs[i]);if(!segments.has(key))segments.set(key,[]);segments.get(key).push(l)}});
 visibleLinks.filter(l=>l.is_trunk&&l.trunk_group).forEach(trunk=>{let latlngs=trunk.geometry.coordinates.map(p=>[p[1],p[0]]);L.polyline(latlngs,{color:'#111827',weight:weight+6,opacity:.78,interactive:false,className:'eth-trunk-sleeve'}).addTo(suggestedBorders)});
 visibleLinks.forEach(l=>{
  let display=separatedCoordinates(l,segments),latlngs=display.map(p=>[p[1],p[0]]);l.display_coordinates=display;
  if(l.route_mode==='suggested')L.polyline(latlngs,{color:'#0284c7',weight:weight+4,opacity:.95,interactive:false,className:'suggested-route-border'}).addTo(suggestedBorders);
  let state=l.status==='up'?'up':l.status==='down'?'down':l.status==='provisional'?'provisional':'unknown',layer=L.polyline(latlngs,{color:lineColor(l.status),weight,className:`net-link net-link-${state} ${l.is_trunk?'eth-trunk-main':''}`,bubblingMouseEvents:false});layer.linkId=l.id;linkLayers.set(Number(l.id),layer);layer.on('click',e=>chooseLinkAt(e.latlng,l));layer.on('contextmenu',e=>{if(e.originalEvent)L.DomEvent.preventDefault(e.originalEvent);if(mode)return;let popup=L.popup({closeButton:true}).setLatLng(e.latlng).setContent(`<div class="link-menu"><b>${esc(l.name)}</b>${l.is_trunk?'<small>Eth-Trunk</small>':l.route_mode==='suggested'?'<small>Trajeto sugerido</small>':''}${ponInterface(l.source_interface_name)||ponInterface(l.target_interface_name)?'<small>Fibra GPON</small>':''}<button id="openLinkDetails">Abrir detalhes</button><button id="removeLinkHere" class="danger">Excluir enlace</button></div>`).openOn(map);setTimeout(()=>{let open=document.getElementById('openLinkDetails'),remove=document.getElementById('removeLinkHere');if(open)open.onclick=()=>{map.closePopup(popup);openLinkPanel(l,layer,e.latlng)};if(remove)remove.onclick=()=>{map.closePopup(popup);deleteLinkConfirmed(l)}},0)});editable.addLayer(layer);
  let flow=ponFlowCoordinates(l,display);if(flow){let flowLatLngs=flow.map(p=>[p[1],p[0]]);L.polyline(flowLatLngs,{color:'#e0f2fe',weight:Math.max(.8,Math.min(1.5,weight*.3)),opacity:.9,interactive:false,className:`pon-fiber-flow pon-fiber-flow-${state}`,pane:'overlayPane'}).addTo(ponFlowLayers)}
 })
}
loadLinks=async function(){links=await api('/api/links');renderLinks();updateCriticalAlerts().catch(()=>{})};
map.on('zoomend',()=>{if(!mode&&!document.querySelector('.leaflet-editing-icon')&&links.length)renderLinks()});

function openIssueForm(target){let coordinate=target.kind==='link'&&Number.isFinite(target.latitude)&&Number.isFinite(target.longitude)?`<div class="issue-card"><small>Ponto selecionado no enlace</small><br><b>${target.latitude.toFixed(6)}, ${target.longitude.toFixed(6)}</b></div>`:'';modal('Reportar erro',`<form id="issueForm"><p><b>${esc(target.name)}</b></p>${coordinate}<label>Classificação</label><select id="issueSeverity"><option value="medium">Médio — amarelo</option><option value="severe">Grave — laranja</option><option value="disaster">Desastre — vermelho</option></select><label>Descrição breve</label><textarea id="issueDescription" maxlength="1000" required style="width:100%;min-height:95px;background:#091526;color:#fff;border:1px solid #38506f;border-radius:6px;padding:9px"></textarea><p id="issueError" class="form-error"></p><button class="primary" type="submit">Reportar erro</button></form>`);document.getElementById('issueForm').onsubmit=async e=>{e.preventDefault();try{let result=await api('/api/issues',{method:'POST',body:JSON.stringify({target_kind:target.kind,target_id:target.id,target_name:target.name,severity:document.getElementById('issueSeverity').value,description:document.getElementById('issueDescription').value.trim(),latitude:target.latitude??null,longitude:target.longitude??null})});closeModal();await loadIssues(false);hint(result.status==='pending'?'Erro enviado para validação.':'Erro registrado e validado.')}catch(x){document.getElementById('issueError').textContent=x.message}}};
function issueRank(s){return s==='disaster'?3:s==='severe'?2:1}
function badgeFor(issue){let isX=issue.status!=='pending'&&issue.severity==='disaster',symbol=issue.status==='pending'?'?':isX?'':'!';return L.divIcon({className:'',iconSize:[24,24],iconAnchor:[12,12],html:`<div class="issue-badge issue-${issue.severity} ${isX?'issue-x':''}">${symbol}</div>`})}
function issueLabel(value){return({medium:'Médio',severe:'Grave',disaster:'Desastre',pending:'Pendente de validação',validated:'Validado',resolved:'Resolvido'})[value]||value}
function showIssueDetails(issue){let coordinate=issue.latitude!=null&&issue.longitude!=null?`<br><b>Coordenada:</b> ${Number(issue.latitude).toFixed(6)}, ${Number(issue.longitude).toFixed(6)}`:'';modal('Detalhes do erro',`<div class="issue-card"><h3>${esc(issue.target_name)}</h3><p><b>Classificação:</b> ${esc(issueLabel(issue.severity))}<br><b>Status:</b> ${esc(issueLabel(issue.status))}<br><b>Reportado por:</b> ${esc(issue.reported_by_name)}${issue.validated_by_name?`<br><b>Validado por:</b> ${esc(issue.validated_by_name)}`:''}${coordinate}</p><p>${esc(issue.description)}</p><small>Registrado em ${new Date(issue.created_at).toLocaleString('pt-BR')}</small>${issue.status==='pending'&&canOperate()?`<button id="detailValidate" class="panel-action">Validar erro</button>`:''}${issue.status!=='resolved'&&canOperate()?`<button id="detailResolve" class="panel-action">Marcar como resolvido</button>`:''}</div>`);let validate=document.getElementById('detailValidate'),resolve=document.getElementById('detailResolve');if(validate)validate.onclick=async()=>{await api(`/api/issues/${issue.id}/validate`,{method:'POST'});closeModal();await loadIssues(false);hint('Erro validado.')} ;if(resolve)resolve.onclick=async()=>{await api(`/api/issues/${issue.id}/resolve`,{method:'POST'});closeModal();await loadIssues(false);hint('Erro marcado como resolvido.')}}
function linkMidpoint(cs){if(!cs||!cs.length)return null;if(cs.length===1)return L.latLng(cs[0][1],cs[0][0]);let segments=[],total=0;for(let i=1;i<cs.length;i++){let a=L.latLng(cs[i-1][1],cs[i-1][0]),b=L.latLng(cs[i][1],cs[i][0]),length=map.distance(a,b);segments.push({a,b,length});total+=length}let wanted=total/2,walked=0;for(let s of segments){if(walked+s.length>=wanted){let t=s.length?(wanted-walked)/s.length:0;return L.latLng(s.a.lat+(s.b.lat-s.a.lat)*t,s.a.lng+(s.b.lng-s.a.lng)*t)}walked+=s.length}let last=cs[cs.length-1];return L.latLng(last[1],last[0])}
function refreshIssueVisibility(){let z=map.getZoom(),popView=z<=15;issueMarkers.forEach(b=>{let hide=false;if(b.issue.target_kind==='device')hide=popView;else if(b.issue.target_kind==='node'){let target=markers.get(`cto:${b.issue.target_id}`)||markers.get(`cloud:${b.issue.target_id}`)||markers.get(`host:${b.issue.target_id}`);hide=target&&((target.net.kind==='cto'&&z<16)||(target.net.kind==='cloud'&&z<14))}if(hide){if(map.hasLayer(b))map.removeLayer(b)}else if(!map.hasLayer(b))b.addTo(map)})}
function refreshIssueMarkers(issues){issueMarkers.forEach(m=>map.removeLayer(m));issueMarkers=[];let selected=new Map();issues.filter(i=>i.status!=='resolved').forEach(i=>{let k=`${i.target_kind}:${i.target_id}`,old=selected.get(k);if(!old||issueRank(i.severity)>issueRank(old.severity)||i.status==='pending'&&old.status!=='pending')selected.set(k,i)});selected.forEach(i=>{let point=null;if(i.target_kind==='link'){if(i.latitude!=null&&i.longitude!=null)point=L.latLng(Number(i.latitude),Number(i.longitude));else{let l=links.find(x=>Number(x.id)===Number(i.target_id));if(l)point=linkMidpoint(l.display_coordinates||l.geometry.coordinates)}}else{let m=markers.get(`${i.target_kind==='node'?'cto':'device'}:${i.target_id}`)||markers.get(`host:${i.target_id}`);if(m)point=m.getLatLng()}if(point){let b=L.marker(point,{icon:badgeFor(i),interactive:true,zIndexOffset:2000});b.issue=i;b.on('click',e=>{if(e.originalEvent)L.DomEvent.stopPropagation(e.originalEvent);showIssueDetails(i)});b.addTo(map);issueMarkers.push(b)}});refreshIssueVisibility()}
async function loadIssues(notify=true){let issues=await api('/api/issues');currentIssues=issues;let open=issues.filter(i=>i.status!=='resolved'),pending=open.filter(i=>i.status==='pending');document.getElementById('issueCount').textContent=open.length;document.getElementById('issuesButton').title=`${open.length} erro${open.length===1?'':'s'} aberto${open.length===1?'':'s'}`;refreshIssueMarkers(issues);if(notify&&['admin','superadmin'].includes(netUser.role)){let fresh=pending.filter(i=>!seenPending.has(i.id));if(fresh.length)showIssueInbox(pending)}pending.forEach(i=>seenPending.add(i.id));updateCriticalAlerts().catch(()=>{});return issues}
async function showIssueInbox(items=null){items=items||await api('/api/issues');let open=items.filter(i=>i.status!=='resolved');modal('Erros da rede',`<div class="issue-list">${open.map(i=>`<div class="issue-card"><b class="${i.severity==='medium'?'unkdot':i.severity==='severe'?'': 'downdot'}">${esc(i.target_name)} · ${esc(i.severity)}</b><p>${esc(i.description)}</p><small>${esc(i.reported_by_name)} · ${esc(i.status)}</small>${i.status==='pending'&&canOperate()?`<button class="validateIssue" data-id="${i.id}">Validar</button>`:''}${i.status!=='resolved'&&canOperate()?`<button class="resolveIssue" data-id="${i.id}">Resolver</button>`:''}</div>`).join('')||'<p>Nenhum erro aberto.</p>'}</div>`);document.querySelectorAll('.validateIssue').forEach(b=>b.onclick=async()=>{await api(`/api/issues/${b.dataset.id}/validate`,{method:'POST'});await showIssueInbox(await loadIssues(false))});document.querySelectorAll('.resolveIssue').forEach(b=>b.onclick=async()=>{await api(`/api/issues/${b.dataset.id}/resolve`,{method:'POST'});await showIssueInbox(await loadIssues(false))})}
document.getElementById('issuesButton').onclick=()=>showIssueInbox();
function licenseMessage(l){if(!l.configured)return'<p>Nenhuma chave foi ativada neste NetAtlas.</p>';if(l.valid)return`<p class="updot"><b>Licença válida</b></p><p>Chave: ${esc(l.license_key)}<br>Verificada: ${l.last_checked_at?new Date(l.last_checked_at).toLocaleString('pt-BR'):'agora'}${l.details?.expires_at?`<br>Expira em: ${esc(new Date(l.details.expires_at).toLocaleDateString('pt-BR'))}`:''}${l.details?.days_remaining!=null?` · ${esc(l.details.days_remaining)} dias restantes`:''}</p>`;return`<p class="downdot"><b>Licença não validada</b></p><p>${esc(l.details?.reason||'Verifique a chave e a conexão com o servidor de licenças.')}</p>`}
async function showLicense(required=false){let l=await api('/api/license');modal('Licença · LVL - NetAtlas',`${required?'<p class="downdot"><b>É necessário ativar uma licença válida para utilizar esta instalação.</b></p>':''}${licenseMessage(l)}<form id="licenseForm"><label>Chave de licença</label><input id="licenseKey" required autocomplete="off" placeholder="Cole a chave aqui"><p id="licenseError" class="form-error"></p><button class="primary" type="submit">Ativar e validar</button>${l.configured?'<button id="licenseRecheck" type="button">Validar novamente</button>':''}</form>`);if(required){let cancel=document.querySelector('#modal>.box>button');if(cancel)cancel.style.display='none'}document.getElementById('licenseForm').onsubmit=async e=>{e.preventDefault();let error=document.getElementById('licenseError');error.textContent='Validando…';try{await api('/api/license/activate',{method:'POST',body:JSON.stringify({license_key:document.getElementById('licenseKey').value})});required?location.reload():(closeModal(),hint('Licença ativada e validada com sucesso.'))}catch(x){error.textContent=x.message}};let check=document.getElementById('licenseRecheck');if(check)check.onclick=async()=>{try{await api('/api/license/check',{method:'POST'});required?location.reload():(closeModal(),hint('Licença validada com sucesso.'))}catch(x){document.getElementById('licenseError').textContent=x.message}}}
document.getElementById('licenseButton').onclick=()=>showLicense().catch(e=>hint(e.message));
async function showUpdates(){modal('Atualizações do NetAtlas','<p class="muted">Consultando o repositório oficial no GitHub…</p>');try{let data=await api('/api/update/status'),short=value=>(value||'—').slice(0,7),changes=data.commits||[],state=data.available?'Nova atualização disponível':data.local_ahead?'Versão local ainda não publicada no GitHub':'NetAtlas atualizado';document.getElementById('modalBody').innerHTML=`<div class="issue-card"><b>${state}</b><p>Instalada: <code>${esc(short(data.current))}</code><br>GitHub: <code>${esc(short(data.latest))}</code></p>${data.local_ahead?'<p class="muted">Esta instalação possui alterações mais novas que o repositório remoto.</p>':changes.length?`<details><summary>Ver alterações (${changes.length})</summary>${changes.map(change=>`<p><code>${esc(change.sha)}</code> · ${esc(change.message)}</p>`).join('')}</details>`:'<p class="muted">Não há alterações pendentes.</p>'}</div><p id="updateError" class="form-error"></p>${data.available?'<button id="applyNetAtlasUpdate" class="primary">Baixar e instalar atualização</button>':''}`;let apply=document.getElementById('applyNetAtlasUpdate');if(apply)apply.onclick=async()=>{let confirmed=await confirmForm('Instalar atualização','A aplicação será atualizada pelo GitHub e reiniciada. O mapa poderá ficar indisponível por alguns segundos.','Instalar agora');if(!confirmed)return;modal('Atualizando NetAtlas','<p>Baixando a atualização e reiniciando o serviço…</p><p class="muted">Esta página será recarregada automaticamente.</p>');try{await api('/api/update/apply',{method:'POST',body:'{}'});setTimeout(()=>location.reload(),15000)}catch(error){document.getElementById('modalBody').innerHTML=`<p class="form-error">${esc(error.message)}</p>`}}}catch(error){document.getElementById('modalBody').innerHTML=`<p class="form-error">${esc(error.message)}</p>`}}
document.getElementById('updateButton').onclick=()=>showUpdates();
async function showAuditLog(){let events=await api('/api/audit?limit=300');modal('Log de ações',`<div class="issue-list">${events.map(x=>`<div class="issue-card"><b>${esc(x.action)}</b><br><small>${esc(x.actor_username)} · ${esc(x.actor_role)} · ${new Date(x.created_at).toLocaleString('pt-BR')}</small><p>${esc(x.target_kind)}${x.target_name?` · ${esc(x.target_name)}`:x.target_id?` #${esc(x.target_id)}`:''}</p>${x.details&&Object.keys(x.details).length?`<small>${esc(Object.entries(x.details).map(([k,v])=>`${k}: ${typeof v==='object'?JSON.stringify(v):v}`).join(' · '))}</small>`:''}</div>`).join('')||'<p>Nenhuma alteração registrada ainda.</p>'}</div>`)}
document.getElementById('auditButton').onclick=()=>showAuditLog().catch(e=>hint(e.message));
document.getElementById('usersButton').onclick=()=>{modal('Criar usuário',`<form id="userForm"><label>Usuário</label><input id="newUsername" required minlength="3"><label>Nome</label><input id="newDisplayName" required><label>Perfil</label><select id="newRole"><option value="admin">Admin</option><option value="technician">Técnico</option><option value="superadmin">Superadmin</option></select><label>Senha inicial</label><input id="newPassword" type="password" required minlength="8"><p id="userError" class="form-error"></p><button class="primary" type="submit">Criar usuário</button></form>`);document.getElementById('userForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/users',{method:'POST',body:JSON.stringify({username:document.getElementById('newUsername').value,display_name:document.getElementById('newDisplayName').value,role:document.getElementById('newRole').value,password:document.getElementById('newPassword').value})});closeModal();hint('Usuário criado com sucesso.')}catch(x){document.getElementById('userError').textContent=x.message}}};

async function showPopManagement(){
 let pops=await api('/api/pops');modal('Gerenciar POPs',`<p class="muted">POPs só podem ser excluídos quando não possuem hosts, CTOs ou outros elementos vinculados no NetBox.</p><div class="management-list">${pops.map(pop=>`<div class="management-row"><div><b>${esc(pop.name)}</b><small>${Number(pop.latitude).toFixed(6)}, ${Number(pop.longitude).toFixed(6)} · ${pop.device_count} elemento${pop.device_count===1?'':'s'}</small></div><button class="danger delete-managed-pop" data-id="${pop.id}" data-name="${esc(pop.name)}" ${pop.device_count?'disabled title="Remova ou mova os elementos primeiro"':''}>Excluir</button></div>`).join('')||'<p>Nenhum POP cadastrado.</p>'}</div><p id="popManagementError" class="form-error"></p>`);
 document.querySelectorAll('.delete-managed-pop').forEach(button=>button.onclick=async()=>{let ok=await confirmForm('Excluir POP',`Deseja excluir definitivamente o POP “${button.dataset.name}”?`,'Excluir POP');if(!ok)return;try{await api(`/api/pops/${button.dataset.id}`,{method:'DELETE'});flashHint(`POP ${button.dataset.name} excluído.`,5000);await loadTopology();await showPopManagement()}catch(error){let target=document.getElementById('popManagementError');if(target)target.textContent=error.message}})
}
async function showHostManagement(){
 let hosts=await api('/api/inventory/hosts');modal('Gerenciar Hosts',`<p class="muted">A exclusão remove o host e suas interfaces do NetBox, libera a licença e também remove enlaces e erros associados.</p><input id="managedHostSearch" autocomplete="off" placeholder="Buscar host ou POP"><div id="managedHostList" class="management-list"></div><p id="hostManagementError" class="form-error"></p>`);let search=document.getElementById('managedHostSearch'),list=document.getElementById('managedHostList');
 function render(){let term=search.value.trim().toLocaleLowerCase('pt-BR'),visible=hosts.filter(host=>`${host.name} ${host.site||''}`.toLocaleLowerCase('pt-BR').includes(term));list.innerHTML=visible.map(host=>`<div class="management-row"><div><b>${esc(host.name)}</b><small>${esc(host.site||'Sem POP')} · ${host.zabbix_hostid?`Zabbix #${host.zabbix_hostid}`:'Host local'} · ${esc(host.status)}</small></div><button class="danger delete-managed-host" data-id="${host.id}" data-name="${esc(host.name)}">Excluir</button></div>`).join('')||'<p>Nenhum host encontrado.</p>';document.querySelectorAll('.delete-managed-host').forEach(button=>button.onclick=async()=>{let ok=await confirmForm('Excluir Host',`Deseja excluir definitivamente o host “${button.dataset.name}”? O host, suas interfaces, enlaces e erros associados serão removidos.`,'Excluir Host');if(!ok)return;try{await api(`/api/devices/${button.dataset.id}`,{method:'DELETE'});hosts=hosts.filter(host=>Number(host.id)!==Number(button.dataset.id));render();await Promise.all([loadTopology(),loadLinks(),loadIssues(false)]);flashHint(`Host ${button.dataset.name} excluído.`,5000)}catch(error){let target=document.getElementById('hostManagementError');if(target)target.textContent=error.message}})}search.oninput=render;render();search.focus()
}
document.getElementById('managePopsButton').onclick=()=>showPopManagement().catch(error=>hint(error.message));
document.getElementById('manageHostsButton').onclick=()=>showHostManagement().catch(error=>hint(error.message));

function safeToRefresh(){return!mode&&!document.querySelector('.leaflet-editing-icon')}
let operationalRefreshRunning=false;
async function refreshOperationalStatus(){if(!safeToRefresh()||operationalRefreshRunning)return;operationalRefreshRunning=true;try{let hostIds=[...new Set([...markers.values()].map(m=>m.net.zabbix_hostid).filter(Boolean).map(Number))];if(hostIds.length){let states=await api(`/api/host-statuses?ids=${hostIds.join(',')}`),byId=new Map(states.map(s=>[Number(s.hostid),s]));for(let m of markers.values()){let hid=Number(m.net.zabbix_hostid),s=byId.get(hid);if(!s)continue;m.net.availability=s.availability;m.net.zabbix_status=s.status;m.net.ips=s.ips;m.net.down=Number(s.availability)===2;m.setIcon(mkIcon(m.net))}}await loadLinks();refreshMarkers()}finally{operationalRefreshRunning=false}}
async function refreshActiveMetrics(){if(!safeToRefresh()||!activeMetricsPanel)return;let selected=activeMetricsPanel;if(selected.kind==='host')return;if(!document.getElementById('linkDialog')?.classList.contains('show'))return;let l=links.find(x=>Number(x.id)===selected.id),layer=null;editable.eachLayer(x=>{if(Number(x.linkId)===selected.id)layer=x});if(l&&layer)await openLinkPanel(l,layer,selected.clickedLatLng)}
map.on('zoomend',renderOntMapClients);
map.on('click',async event=>{if(mode!=='ont-position'||!pendingOntPosition)return;let client=pendingOntPosition;pendingOntPosition=null;try{await api(`/api/cto-clients/${client.assignment_id}/position`,{method:'PATCH',body:JSON.stringify({latitude:event.latlng.lat,longitude:event.latlng.lng})});cancel();await loadOntMapClients();map.setView(event.latlng,Math.max(map.getZoom(),18));flashHint(`ONT ${client.number||client.ont_number} posicionada no mapa.`,5000)}catch(error){mode='ont-position';pendingOntPosition=client;flashHint(error.message,6000)}});
const portalCancel=cancel;cancel=function(){pendingOntPosition=null;pendingOperatorPosition=null;portalCancel()};
async function refreshOtherInformation(){if(!safeToRefresh())return;await Promise.all([loadIssues(true),loadOperatorCards(),loadOntMapClients()])}
async function startNetAtlas(){let r=await fetch('/api/auth/me');if(!r.ok){showLogin();return}netUser=await r.json();applyRole();let license=await api('/api/license');if(!license.valid){await showLicense(true);return}await Promise.all([loadTopology(),loadLinks()]);await Promise.all([loadIssues(true),loadOperatorCards(),loadOntMapClients()]);setInterval(()=>refreshOperationalStatus().catch(e=>hint(e.message)),30000);setInterval(()=>refreshActiveMetrics().catch(e=>hint(e.message)),120000);setInterval(()=>refreshOtherInformation().catch(e=>hint(e.message)),180000)}
